function reviewTutorialBookmarks(){
 const list=S.settings.publicTutorialBookmarks;if(list===undefined)return [];
 const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),strings=(v,keys)=>keys.every(k=>typeof v[k]==='string'&&v[k].length>0),only=(v,keys)=>Object.keys(v).every(k=>keys.includes(k)),hash=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v),seen=new Set();
 const invalid=()=>{throw Error('收藏资料不完整，原资料已保留。请先导出本机档案，再从有效备份恢复。')};
 if(!Array.isArray(list))invalid();
 for(const b of list){
  if(!object(b)||!only(b,['tutorial','snapshotHash'])||!hash(b.snapshotHash))invalid();const t=b.tutorial;
  if(!object(t)||!only(t,['id','treeId','nodeId','authorId','authorName','version','createdAt','kind','target','title','method','startAction','resources','visibility'])||!strings(t,['id','treeId','nodeId','authorId','authorName','createdAt','title','method'])||typeof t.startAction!=='string'||!hash(t.version)||!Number.isFinite(Date.parse(t.createdAt))||t.visibility!=='public'||!['catalog','personal-public'].includes(t.kind)||!Array.isArray(t.resources))invalid();
  if(t.resources.some(r=>!object(r)||!only(r,['label','url','optional','affiliate'])||!strings(r,['label','url'])||typeof r.optional!=='boolean'||typeof r.affiliate!=='boolean'))invalid();
  const n=t.target,keys=t.kind==='catalog'?['id','treeId','originId','sourceVersion','title','goal','five','domain','branch','ownership','ownerId','visibility','source','version']:['nodeId','treeId','title','goal','five','domain','branch','version','sourceVersion','ownership','visibility','ownerId','ownerName'];
  if(!object(n)||!only(n,keys)||!strings(n,['treeId','title','goal','five','domain','branch','version'])||n.treeId!==t.treeId||!Number.isInteger(n.sourceVersion)||n.sourceVersion<1||n.visibility!=='public')invalid();
  if(t.kind==='catalog'?(n.id!==t.nodeId||typeof n.originId!=='string'||n.ownership!=='group'||n.ownerId!==null):(n.nodeId!==t.nodeId||n.ownership!=='personal'||!strings(n,['ownerId','ownerName'])))invalid();
  const key=JSON.stringify([t.id,t.version]);if(seen.has(key))invalid();seen.add(key);
 }
 return list;
}
async function reviewCheckedTutorialBookmarks(){
 const raw=JSON.stringify(reviewTutorialBookmarks()),list=JSON.parse(raw);
 if(list.length&&!crypto.subtle?.digest)throw Error('当前浏览器无法核对收藏完整性，原资料已保留。可先导出本机档案。');
 const digest=async v=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(v)))),b=>b.toString(16).padStart(2,'0')).join('');
 for(const b of list){const t=b.tutorial,n=t.target;
  const resources=t.resources.map(r=>{const url=new URL(r.url);if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.href.length>2000||!r.label.trim()||r.label.trim().length>80)throw Error('收藏材料无法核对，原资料已保留。请先导出本机档案。');return {label:r.label.trim(),url:url.href,affiliate:r.affiliate===true,optional:r.optional!==false}});
  if(!t.title.trim()||t.title.trim().length>80||!t.method.trim()||t.method.trim().length>8000||t.startAction.trim().length>240||resources.length>12)throw Error('收藏方法无法核对，原资料已保留。请先导出本机档案。');
  const method={title:t.title.trim(),method:t.method.trim(),startAction:t.startAction.trim(),resources,visibility:'public'};
  if(await digest(t)!==b.snapshotHash||await digest(method)!==t.version||t.kind==='catalog'&&await digest({title:n.title,goal:n.goal,five:n.five,domain:n.domain,branch:n.branch,ownership:n.ownership})!==n.version)throw Error('收藏内容与原版本不一致，原资料已保留。请先导出本机档案，再从有效备份恢复。');
 }
 if(JSON.stringify(reviewTutorialBookmarks())!==raw)throw Error('核对期间收藏已变化，请重新读取；原资料保留。');
 return {raw,list};
}
async function reviewCheckSelectedTutorial(t){const checked=await reviewCheckedTutorialBookmarks();if(!checked.list.some(b=>JSON.stringify(b.tutorial)===JSON.stringify(t)))throw Error('所选收藏已变化，请重新读取；原资料保留。');return checked}
function reviewTutorialCompareFields(t){const n=t.target;return [
 {key:'title',label:'方法标题',value:t.title,html:esc(t.title)},
 {key:'goalTitle',label:'目标名称',value:n.title,html:esc(n.title)},
 {key:'goal',label:'完整目标',value:n.goal,html:esc(n.goal)},
 {key:'classification',label:'目标领域与分支',value:JSON.stringify([n.domain,n.branch]),html:esc(n.domain+' / '+n.branch)},
 {key:'goalFive',label:'目标起步建议',value:n.five,html:esc(n.five)},
 {key:'ownership',label:'目标归属',value:JSON.stringify([n.ownership,n.ownerId,n.ownerName||'']),html:n.ownership==='personal'?'个人持有人：'+esc(n.ownerName):'公共节点 · 属于全部点亮者'},
 {key:'method',label:'方法',value:t.method,html:esc(t.method)},
 {key:'five',label:'教程五分钟起步',value:t.startAction,html:esc(t.startAction)},
 {key:'resources',label:'材料与产品链接',value:JSON.stringify(t.resources),html:t.resources.length?t.resources.map(reviewResourceLink).join(''):'<p class="small muted">这一版本没有关联材料。</p>'}
]}
function reviewTutorialVersionColumn(t,label,changes=[]){return `<section class="box" style="flex:1 1 300px;min-width:0;overflow-wrap:anywhere"><h3>${label}</h3><p class="small muted">${esc(t.authorName)} · ${esc(t.version.slice(0,8))}<br>目标版本 ${esc(t.target.version.slice(0,8))} · ${t.target.sourceVersion}<br>版本发布 ${esc(dt(Date.parse(t.createdAt)))}</p>${reviewTutorialCompareFields(t).map(f=>`<div data-comparison-field="${f.key}" data-changed="${changes.includes(f.key)}" style="margin:16px 0;${changes.includes(f.key)?'border-left:2px solid var(--accent);padding-left:12px':''}"><h4>${f.label}${changes.includes(f.key)?' <span class="tag">已变化</span>':''}</h4>${f.key==='resources'?f.html:`<p class="pre">${f.html}</p>`}</div>`).join('')}</section>`}
function reviewTutorialChangeSummary(old,now,changes){const fields=reviewTutorialCompareFields(old),metadata=[];if(old.createdAt!==now.createdAt)metadata.push('版本发布时间');if(old.target.version!==now.target.version||old.target.sourceVersion!==now.target.sourceVersion)metadata.push('目标版本标记');if(old.authorName!==now.authorName)metadata.push('作者显示名称');return `<div id="tutorial-comparison-summary" class="box" style="margin-bottom:16px"><h3>变化概览</h3>${changes.length?'<p>内容变化：'+changes.map(k=>fields.find(f=>f.key===k).label).join('、')+'。</p>':'<p>目标、方法与材料内容一致。</p>'}${metadata.length?'<p class="small muted">版本信息变化：'+metadata.join('、')+'。</p>':''}<label class="check-row"><input id="tutorial-comparison-only-changes" type="checkbox">只看变化的内容</label><p class="small muted">取消勾选可查看两版完整内容。</p></div>`}

async function reviewCompareBookmarkedTutorial(t,context,button){
 if(!button.isConnected||button.disabled||!reviewContextCurrent(context))return;button.disabled=true;
 modal(`<section id="tutorial-version-loading"><h2>核对当前公开版本</h2><p role="status">正在读取当前内容，原收藏保留…</p></section>`,'','教程版本对照');const loading=document.getElementById('tutorial-version-loading');let verified=false;
 try{const checked=await reviewCheckSelectedTutorial(t);if(!loading.isConnected||!reviewContextCurrent(context))return;t=checked.list.find(b=>JSON.stringify(b.tutorial)===JSON.stringify(t)).tutorial;verified=true;const r=await reviewKnowledgeRequest('/api/review-public-tutorials/one?id='+encodeURIComponent(t.id),{context});if(!loading.isConnected||!reviewContextCurrent(context))return;const now=r.tutorial;if(r.ownerId!==context.ownerId||!now||now.id!==t.id||now.authorId!==t.authorId)throw Error('当前教程身份未能核对，原收藏保留。');const oldFields=reviewTutorialCompareFields(t),newFields=reviewTutorialCompareFields(now),changes=oldFields.filter((f,i)=>f.value!==newFields[i].value).map(f=>f.key),changed=changes.length>0;const comparison=modal(`<section id="tutorial-version-comparison"><h2>教程版本对照</h2><p class="small muted">${changed?'当前公开内容与收藏版本不同。':'内容一致，版本信息单独列示。'}旧收藏保留，查看与收藏不会开始计时。</p>${reviewTutorialChangeSummary(t,now,changes)}<div style="display:flex;flex-wrap:wrap;gap:16px">${reviewTutorialVersionColumn(t,'收藏时的版本',changes)}${reviewTutorialVersionColumn(now,'当前公开版本',changes)}</div><div class="row" style="margin-top:16px">${reviewTutorialVersionLink(t.treeId,t.nodeId,t.id,t.version,'打开收藏时的教程版本')}${reviewTutorialVersionLink(now.treeId,now.nodeId,now.id,now.version,'打开当前公开教程版本')}<button class="ghost" id="tutorial-comparison-save">收藏当前版本</button><button class="ghost" id="tutorial-comparison-open">核对当前版本并查看目标</button><button class="ghost" id="tutorial-comparison-refresh">重新核对当前版本</button></div><p id="tutorial-comparison-status" role="status"></p></section>`,'','教程版本对照');comparison.style.width='min(980px,calc(100vw - 32px))';const host=document.getElementById('tutorial-version-comparison'),status=document.getElementById('tutorial-comparison-status');document.getElementById('tutorial-comparison-only-changes').onchange=e=>{if(host.isConnected&&reviewContextCurrent(context))host.querySelectorAll('[data-comparison-field]').forEach(f=>f.hidden=e.target.checked&&f.dataset.changed!=='true')};document.getElementById('tutorial-comparison-save').onclick=e=>{if(host.isConnected&&reviewContextCurrent(context))reviewBookmarkTutorial(now,context,e.currentTarget,status)};document.getElementById('tutorial-comparison-refresh').onclick=e=>{if(host.isConnected&&reviewContextCurrent(context))reviewCompareBookmarkedTutorial(t,context,e.currentTarget)};document.getElementById('tutorial-comparison-open').onclick=e=>{if(host.isConnected&&reviewContextCurrent(context))reviewOpenSearchTarget(now,context,e.currentTarget,status)};
 }catch(e){if(!loading.isConnected||!reviewContextCurrent(context))return;modal(`<section id="tutorial-version-comparison"><h2>教程版本对照</h2><p class="error" role="alert">${esc(reviewIsNetworkError(e)?'当前版本读取未确认，请重试。':e.message)}</p>${verified?reviewTutorialVersionColumn(t,'收藏时的版本'):btn('导出本机档案','review-sync-export','ghost')}<button id="tutorial-comparison-retry" class="ghost">重新核对当前版本</button></section>`,'','教程版本对照');const retry=document.getElementById('tutorial-comparison-retry');if(retry&&reviewContextCurrent(context))retry.onclick=e=>reviewCompareBookmarkedTutorial(t,context,e.currentTarget)}finally{if(button.isConnected&&reviewContextCurrent(context))button.disabled=false}
}
async function reviewOpenBookmarkedTutorial(t,context,button,status){if(!button.isConnected||button.disabled||!reviewContextCurrent(context))return;button.disabled=true;try{await reviewCheckSelectedTutorial(t);if(!button.isConnected||!reviewContextCurrent(context))return;const r=await reviewKnowledgeRequest('/api/review-public-tutorials/one?id='+encodeURIComponent(t.id),{context});if(!button.isConnected||!reviewContextCurrent(context))return;const comparable=v=>{const copy=clone(v);delete copy.createdAt;return JSON.stringify(copy)};if(r.ownerId!==context.ownerId||!r.tutorial||comparable(r.tutorial)!==comparable(t))throw Error('收藏的方法或目标已变化，请重新读取；原收藏保留。');button.disabled=false;await reviewOpenSearchTarget(r.tutorial,context,button,status)}catch(e){if(button.isConnected&&reviewContextCurrent(context))status.textContent=reviewIsNetworkError(e)?'收藏入口读取未确认，请重试；原快照保留。':e.message}finally{if(button.isConnected&&reviewContextCurrent(context))button.disabled=false}}
async function reviewBookmarkTutorial(t,context,button,status,refresh=null){if(!reviewContextCurrent(context)||!button.isConnected||button.disabled)return;button.disabled=true;try{await reviewCheckedTutorialBookmarks();if(!button.isConnected||!reviewContextCurrent(context))return;const r=await reviewKnowledgeRequest('/api/review-public-tutorials/one?id='+encodeURIComponent(t.id),{context});if(!button.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId)throw Error('教程归属回执不一致。');
 if(JSON.stringify(r.tutorial)!==JSON.stringify(t)){
  if(refresh)return await refresh('教程已变化，请核对更新后的版本再收藏。');
  throw Error('教程已变化，请重新读取核对；原收藏保留。');
 }if(!crypto.subtle?.digest)throw Error('当前浏览器无法校验收藏内容，请重试。');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(t)));if(!button.isConnected||!reviewContextCurrent(context))return;const entry={tutorial:clone(t),snapshotHash:Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')};const checked=await reviewCheckedTutorialBookmarks();if(!button.isConnected||!reviewContextCurrent(context))return;if(!checked.list.some(b=>b.tutorial.id===t.id&&b.tutorial.version===t.version))S.settings.publicTutorialBookmarks=[...checked.list,entry];if(!save())throw Error('收藏留在当前页面，本机保存未确认，请保留备份。');status.textContent='收藏已留在本机，正在保存到本人账号…';await reviewFlush();if(button.isConnected&&reviewContextCurrent(context)){if(S.page==='savedTutorials')document.getElementById('tutorial-bookmark-search')?.elements.query.dispatchEvent(new Event('input',{bubbles:true}));button.textContent='已收藏这个版本';status.textContent='已收藏完整目标、方法和材料；原作者及版本保留。'}}catch(e){
 if(!button.isConnected||!reviewContextCurrent(context))return;
 if(refresh&&e.code==='PUBLIC_TUTORIAL_UNAVAILABLE')await refresh('教程或目标已不可公开读取。');
 else status.textContent=reviewIsNetworkError(e)?'收藏保存或读取未确认，已保存的内容保留，请重试同步。':e.message;
}finally{if(button.isConnected&&reviewContextCurrent(context))button.disabled=false}}
function reviewTutorialBookmarksPage(){queueMicrotask(()=>reviewBindTutorialBookmarks());return title('收藏教程','保留你读过的方法版本，准备好时再实践。')+`<form id="tutorial-bookmark-search" class="row"><input type="search" name="query" aria-label="搜索收藏教程" placeholder="目标、方法或作者"></form><p id="tutorial-bookmark-status" class="small muted" role="status"></p><div id="tutorial-bookmark-results"></div>`}
function reviewBindTutorialBookmarks(){const form=document.getElementById('tutorial-bookmark-search');if(!form||form.dataset.bound||reviewAuthBusy||reviewAccountConnecting||!S.user?.reviewService)return;form.dataset.bound='true';const context=reviewContext(),host=document.getElementById('tutorial-bookmark-results'),status=document.getElementById('tutorial-bookmark-status');let verifiedRaw=null,generation=0;function failure(e){status.textContent=e.message;host.innerHTML=btn('导出本机档案','review-sync-export','ghost');bind(host)}function draw(){if(!form.isConnected||!reviewContextCurrent(context))return;const attempt=++generation;let all;try{all=reviewTutorialBookmarks()}catch(e){failure(e);return}const raw=JSON.stringify(all);if(raw!==verifiedRaw){status.textContent='正在核对收藏完整性…';host.innerHTML='';reviewCheckedTutorialBookmarks().then(checked=>{if(form.isConnected&&reviewContextCurrent(context)&&attempt===generation){verifiedRaw=checked.raw;draw()}}).catch(e=>{if(form.isConnected&&reviewContextCurrent(context)&&attempt===generation)failure(e)});return}const query=form.elements.query.value.trim().normalize('NFKC').toLowerCase(),rows=all.filter(b=>[b.tutorial.title,b.tutorial.method,b.tutorial.target.goal,b.tutorial.authorName].some(v=>v.normalize('NFKC').toLowerCase().includes(query)));status.textContent=`收藏 ${all.length} 个方法版本，当前 ${rows.length} 个。`;host.innerHTML=rows.map((b,i)=>{const t=b.tutorial;return `<article class="list-row"><h2>${esc(t.title)}</h2><p class="small muted">${esc(t.authorName)} · 收藏版本 ${esc(t.version.slice(0,8))}</p><details><summary>收藏时的完整目标、方法与材料</summary><p class="pre">${esc(t.target.goal)}</p><p class="pre">${esc(t.method)}</p><p class="pre small">五分钟起步：${esc(t.startAction)}</p>${t.resources.map(reviewResourceLink).join('')}</details><button class="ghost" data-tutorial-bookmark-open="${i}">核对当前版本并查看目标</button><button id="tutorial-bookmark-compare-${esc(t.id)}-${esc(t.version)}" class="ghost" data-tutorial-bookmark-compare="${i}">对照当前版本</button><button class="ghost" data-tutorial-bookmark-remove="${i}">取消这个版本收藏</button><p role="status"></p></article>`}).join('')||'<p class="muted">当前没有符合条件的收藏教程。</p>';host.querySelectorAll('[data-tutorial-bookmark-open]').forEach(b=>b.onclick=()=>reviewOpenBookmarkedTutorial(rows[Number(b.dataset.tutorialBookmarkOpen)].tutorial,context,b,b.parentElement.querySelector('[role="status"]')));host.querySelectorAll('[data-tutorial-bookmark-compare]').forEach(b=>b.onclick=()=>reviewCompareBookmarkedTutorial(rows[Number(b.dataset.tutorialBookmarkCompare)].tutorial,context,b));host.querySelectorAll('[data-tutorial-bookmark-remove]').forEach(b=>b.onclick=async()=>{if(!form.isConnected||!b.isConnected||!reviewContextCurrent(context)||b.disabled)return;b.disabled=true;const t=rows[Number(b.dataset.tutorialBookmarkRemove)].tutorial;let removed=false;try{const checked=await reviewCheckSelectedTutorial(t);if(!form.isConnected||!b.isConnected||!reviewContextCurrent(context))return;S.settings.publicTutorialBookmarks=checked.list.filter(v=>v.tutorial.id!==t.id||v.tutorial.version!==t.version);removed=true;save();await reviewFlush()}catch(e){if(form.isConnected&&reviewContextCurrent(context))status.textContent=e.message}if(form.isConnected&&reviewContextCurrent(context)){draw();if(removed&&S.reviewSync?.pending)status.textContent+=' 本机取消已保留，服务保存尚未确认。'}})}form.onsubmit=e=>e.preventDefault();form.elements.query.oninput=draw;draw()}
